-- Revert the demo city spaces and cost_of_living items added by 000591.
BEGIN;

DELETE FROM comparison_values
WHERE item_id IN (
    '00000000-0000-0000-0000-000000000b02',
    '00000000-0000-0000-0000-000000000b03',
    '00000000-0000-0000-0000-000000000b04'
);

DELETE FROM comparison_items
WHERE id IN (
    '00000000-0000-0000-0000-000000000b02',
    '00000000-0000-0000-0000-000000000b03',
    '00000000-0000-0000-0000-000000000b04'
);

-- Restore the baseline Lagos geo_space_id to the old state-level Lagos space, if it still exists.
UPDATE comparison_items
SET geo_space_id = (
    SELECT id FROM spaces
    WHERE tenant_id = '00000000-0000-0000-0000-000000000001'
      AND slug = 'lagos' AND level = 'state'
    LIMIT 1
)
WHERE id = '00000000-0000-0000-0000-000000000b01';

-- Remove the many-to-many parent links for the demo cities.
DELETE FROM space_parent_spaces
WHERE space_id IN (
    '00000000-0000-0000-0000-000000000301',
    '00000000-0000-0000-0000-000000000302',
    '00000000-0000-0000-0000-000000000303',
    '00000000-0000-0000-0000-000000000304'
);

DELETE FROM spaces
WHERE id IN (
    '00000000-0000-0000-0000-000000000101',
    '00000000-0000-0000-0000-000000000102',
    '00000000-0000-0000-0000-000000000103',
    '00000000-0000-0000-0000-000000000201',
    '00000000-0000-0000-0000-000000000202',
    '00000000-0000-0000-0000-000000000203',
    '00000000-0000-0000-0000-000000000204',
    '00000000-0000-0000-0000-000000000301',
    '00000000-0000-0000-0000-000000000302',
    '00000000-0000-0000-0000-000000000303',
    '00000000-0000-0000-0000-000000000304'
);

COMMIT;
